-- name: platform__commands_readrungraphtx_select_run_nodes_organization_id_root_run_id_ref :many
SELECT n.ref,run.ref,COALESCE(parent.ref,''),n.type,n.state,n.display_name,n.role,COALESCE(a.ref,''),COALESCE(t.ref,''),n.attempt,n.input_summary,n.progress_summary,n.integration_names,n.callback_summary,n.safe_error_code,n.safe_error_message,n.next_actions,n.created_at,n.started_at,n.finished_at,'{}'::text[],'{}'::text[] FROM control_plane.run_nodes n JOIN control_plane.runs run ON run.id=n.run_id LEFT JOIN control_plane.run_nodes parent ON parent.id=n.parent_node_id LEFT JOIN control_plane.agents a ON a.id=n.agent_id LEFT JOIN control_plane.session_turns t ON t.id=n.turn_id WHERE n.organization_id=$1::uuid AND (n.root_run_id=(SELECT root_run_id FROM control_plane.runs WHERE ref=$2) OR EXISTS(SELECT 1 FROM control_plane.run_edges e WHERE e.root_run_id=(SELECT root_run_id FROM control_plane.runs WHERE ref=$2) AND (e.source_node_id=n.id OR e.target_node_id=n.id))) ORDER BY n.created_at
